/**
 * Generates `public/firebase-config.js` from env vars (or .env.local).
 *
 * Why: static pages outside the Next.js bundle can't read
 * NEXT_PUBLIC_* env vars the way Next.js pages can. So this script emits a tiny
 * ES module with the client config at dev/build time. The generated file is
 * gitignored, so no keys ever land in the repo.
 *
 * Runs automatically via the `predev` / `prebuild` npm hooks.
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

// --- Load .env.local (lowest priority; real process env wins) --------------
const fileEnv = {};
const envPath = join(root, ".env.local");
if (existsSync(envPath)) {
  for (const line of readFileSync(envPath, "utf8").split("\n")) {
    const m = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/);
    if (m) fileEnv[m[1]] = m[2].replace(/^["']|["']$/g, "");
  }
}
const env = (key) => process.env[key] || fileEnv[key] || "";

const config = {
  apiKey: env("NEXT_PUBLIC_FIREBASE_API_KEY"),
  authDomain: env("NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN"),
  projectId: env("NEXT_PUBLIC_FIREBASE_PROJECT_ID"),
  storageBucket: env("NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET"),
  messagingSenderId: env("NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID"),
  appId: env("NEXT_PUBLIC_FIREBASE_APP_ID"),
};

if (!config.apiKey || !config.projectId) {
  console.error(
    "\n[generate-firebase-config] Missing NEXT_PUBLIC_FIREBASE_* env vars.\n" +
      "Copy .env.example to .env.local and fill in your Firebase config.\n",
  );
  process.exit(1);
}

const out = join(root, "public", "firebase-config.js");
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  "// AUTO-GENERATED by scripts/generate-firebase-config.mjs — do not edit, do not commit.\n" +
    `export const firebaseConfig = ${JSON.stringify(config, null, 2)};\n`,
);
console.log("[generate-firebase-config] Wrote public/firebase-config.js");
